#!/usr/bin/env node
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const arg=n=>{const i=process.argv.indexOf(n);return i<0?null:process.argv[i+1]};
export function buildBundle({sourceRoot,dependenciesPath,output,hostedRoot=null}){
 const root=fs.realpathSync(sourceRoot), dep=JSON.parse(fs.readFileSync(dependenciesPath)); const files=new Map();
 const safe=(p,base=root)=>{if(!p||path.isAbsolute(p)||p.includes('\\'))throw Error('UNSAFE_PATH');const a=path.resolve(base,p);if(!(a.startsWith(root+path.sep)||(hostedRoot&&a.startsWith(fs.realpathSync(hostedRoot)+path.sep))))throw Error('UNSAFE_PATH');if(!fs.existsSync(a)||fs.lstatSync(a).isSymbolicLink()||!fs.statSync(a).isFile())throw Error('MISSING_OR_UNSAFE_SOURCE '+p);return a};
 const add=(p,base=root)=>{const a=safe(p,base), rel=(a.startsWith(root+path.sep)?path.relative(root,a):path.relative(fs.realpathSync(hostedRoot),a)).split(path.sep).join('/');if(files.has(rel))return;const b=fs.readFileSync(a);files.set(rel,{sha256:sha(b),size:b.length,content:b.toString('base64')});for(const m of b.toString().matchAll(/(?:import|export)\s+(?:[^'";]+?\s+from\s+)?['"](\.[^'"]+)['"]/g)){let q=path.resolve(path.dirname(a),m[1]);if(!path.extname(q))q+='.mjs';if(!fs.existsSync(q)&&hostedRoot&&path.basename(q)==='execute-newsstand-hosted-protocol.mjs')add(path.relative(fs.realpathSync(hostedRoot),path.join(fs.realpathSync(hostedRoot),'scripts/execute-newsstand-hosted-protocol.mjs')),fs.realpathSync(hostedRoot));else add(path.relative(root,q),root)}};
 for(const p of [...dep.staticRuntime,...dep.staticPolicy,...dep.mutableBase.filter(x=>!x.includes('YYYY')),'operations/product-stewards/newsstand/review-runtime/protocol-hosted.mjs','operations/product-stewards/newsstand/review-runtime/assemble-hosted-review.mjs','operations/product-stewards/newsstand/review-runtime/run-hosted-pilot.mjs'])add(p);
 // Exact exemplar bytes are data dependencies, not a directory copy.
 const registry=JSON.parse(fs.readFileSync(path.join(root,'operations/product-stewards/learning-content-ecosystem/content-quality-exemplars.json')));for(const x of [...registry.negativeExemplars,...registry.positiveExemplars])if(x.path)add(x.path);
 if(hostedRoot)add('scripts/execute-newsstand-hosted-protocol.mjs',fs.realpathSync(hostedRoot));
 const manifest={schema:'newsstand-hosted-runtime-bundle-v1',files:Object.fromEntries([...files].sort(([a],[b])=>a.localeCompare(b))),totalBytes:[...files.values()].reduce((n,x)=>n+x.size,0)};const json=JSON.stringify(manifest)+'\n';if(fs.existsSync(output))throw Error('OUTPUT_EXISTS');fs.mkdirSync(path.dirname(output),{recursive:true,mode:0o700});fs.writeFileSync(output,json,{mode:0o600,flag:'wx'});return manifest;
}
if(import.meta.url===new URL(process.argv[1],'file:').href){try{const m=buildBundle({sourceRoot:arg('--source-root'),dependenciesPath:arg('--dependencies'),output:arg('--output'),hostedRoot:arg('--hosted-root')});console.log(JSON.stringify({files:Object.keys(m.files).length,totalBytes:m.totalBytes,privateOutput:true}));}catch(e){console.error('HOSTED_RUNTIME_BUNDLE_FAILED '+e.message);process.exitCode=2}}
